arguments.command:
python3 -I -c 'import ast,re,statistics,math,json; p="/workspace/wandb/latest-run/files/output.log"; perf={}; roll={}; ev={};
for n,x in enumerate(open(p),1):
 if " - perf " in x or " - rollout " in x or " - eval " in x:
  d=ast.literal_eval(x[x.index("{"):]); pre=x.split(" - ")[1]; typ,step=pre.split(" ",1); step=int(step.split(":")[0]); target={"perf":perf,"rollout":roll,"eval":ev}[typ]; target[step]=(n,d)
print("COUNTS",len(perf),len(roll),len(ev)); print("STEP LINE RAWREWARD RESP TRUNC LOGP REFL KL ADV");
for s in [0,5,9,10,15,19,20,24,29,30,39,40,49,50,59,60,69,70,79,80,89,90,99,100,109,119,129,139,149,159,169,179,189,190,195,199]:
 n,d=roll[s]; print(s,n,*(d[k] for k in ["rollout/raw_reward","rollout/response_lengths","rollout/truncated","rollout/rollout_log_probs","rollout/ref_log_probs","rollout/kl","rollout/advantages"]))
for a,b in [(0,9),(10,19),(20,39),(40,69),(70,99),(100,199),(0,199)]:
 print("PHASE",a,b)
 for k in ["rollout/raw_reward","rollout/response_lengths","rollout/truncated","rollout/rollout_log_probs","rollout/ref_log_probs","rollout/advantages","rollout/rewards"]:
  vs=[roll[s][1][k] for s in range(a,b+1)]; print(k,"mean",statistics.mean(vs),"sd",statistics.stdev(vs),"min",min(vs),"max",max(vs))
for a,b in [(0,9),(10,19),(20,39),(40,69),(70,99),(100,199)]:
 print("PERF",a,b,"time",statistics.mean([perf[s][1]["perf/rollout_time"] for s in range(a,b+1)]),"tps",statistics.mean([perf[s][1]["perf/tokens_per_gpu_per_sec"] for s in range(a,b+1)]),"zero_std_zero",statistics.mean([perf[s][1].get("rollout/zero_std/count_0",0) for s in range(a,b+1)]),"zero_std_one",statistics.mean([perf[s][1].get("rollout/zero_std/count_1.0",0) for s in range(a,b+1)]))
print("EVAL");
