arguments.command:
python3 -I -c 'import ast,re,statistics,pathlib; p=pathlib.Path("/workspace/wandb/latest-run/files/output.log"); ev={}; ro={}; pe={}; loc={};
for n,s in enumerate(p.read_text().splitlines(),1):
 m=re.search(r"eval (\d+): (\{.*\})",s)
 if m: ev[int(m[1])]=ast.literal_eval(m[2]); loc["e",int(m[1])]=n
 m=re.search(r"perf (\d+): (\{.*\})",s)
 if m: pe[int(m[1])]=ast.literal_eval(m[2]); loc["p",int(m[1])]=n
 m=re.search(r"rollout (\d+): (\{.*\})",s)
 if m: ro[int(m[1])]=ast.literal_eval(m[2]); loc["r",int(m[1])]=n
print("records",len(ev),len(pe),len(ro)); print("eval trajectory"); print(" ".join(f"{i}:{ev[i][chr(101)+chr(118)+chr(97)+chr(108)+chr(47)+chr(110)+chr(113)+chr(95)+chr(116)+chr(101)+chr(115)+chr(116)]:.6f}" for i in sorted(ev))); print("eval after69 mean/min/max",statistics.mean(ev[i]["eval/nq_test"] for i in ev if i>=69),min(ev[i]["eval/nq_test"] for i in ev if i>=69),max(ev[i]["eval/nq_test"] for i in ev if i>=69));
for a,b in [(0,9),(10,19),(20,39),(40,69),(70,99),(100,199)]:
 ix=range(a,b+1); z=lambda i: pe[i].get("rollout/zero_std/count_0",0)+pe[i].get("rollout/zero_std/count_1.0",0); print("phase",a,b,"reward",statistics.mean(ro[i]["rollout/raw_reward"] for i in ix),"len",statistics.mean(pe[i]["rollout/response_len/mean"] for i in ix),"trunc",statistics.mean(pe[i]["rollout/truncated_ratio"] for i in ix),"zero",statistics.mean(z(i) for i in ix),"all0",statistics.mean(pe[i].get("rollout/zero_std/count_0",0) for i in ix),"all1",statistics.mean(pe[i].get("rollout/zero_std/count_1.0",0) for i in ix),"seconds",statistics.mean(pe[i]["perf/rollout_time"] for i in ix),"tok/gpu/s",statistics.mean(pe[i]["perf/tokens_per_gpu_per_sec"] for i in ix))
print("length drops eval/train %",100*(1-ev[199]["eval/nq_test/response_len/mean"]/ev[0]["eval/nq_test/response_len/mean"]),100*(1-pe[199]["rollout/response_len/mean"]/pe[0]["rollout/response_len/mean"])); print("best raw reward",max(ro,key=lambda i:ro[i]["rollout/raw_reward"]),max(x["rollout/raw_reward"] for x in ro.values())); print("late mean length distribution",statistics.median(pe[i]["rollout/response_len/mean"] for i in range(100,200)),min(pe[i]["rollout/response_len/mean"] for i in range(100,200)),max(pe[i]["rollout/response_len/mean"] for i in range(100,200))); print("raw train steps 100+ mean/min/max",statistics.mean(ro[i]["rollout/raw_reward"] for i in range(100,200)),min(ro[i]["rollout/raw_reward"] for i in range(100,200)),max(ro[i]["rollout/raw_reward"] for i in range(100,200)))'

