arguments.command:
python3 -I -c 'import pyarrow.parquet as pq,collections; paths=["/workspace/nq_hotpotqa_train/train.parquet","/workspace/nq_hotpotqa_train/test.parquet"];
for p in paths:
 f=pq.ParquetFile(p); print(p,"rows",f.metadata.num_rows,"columns",f.schema_arrow.names); print("first-row reward_model",f.read_row_group(0).slice(0,1).to_pylist()[0].get("reward_model"))
 if "data_source" in f.schema_arrow.names:
  c=collections.Counter(); first3=collections.Counter()
  for b in f.iter_batches(columns=["data_source"],batch_size=4096):
   vals=b.column(0).to_pylist(); c.update(vals)
  print("sources",c)
'

